# -*- coding: utf-8 -*-
S = "сплошной скан дублей неверных вариантов (набор чисел равен ключу), проверено вычислением"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G11_TB_12_2_12_4_а", "неверный вариант $\\{-\\frac12;0;-\\frac23\\}$ равен ключу (все три корня верны, проверено подстановкой); заменён на потерю корня, пояснения к остальным вариантам очищены от вложенных знаков $",
  dnew={0: (r"$-\dfrac{2}{3}$, $0$, $2$", r"Ученик верно нашёл $x=-\frac{2}{3}$ из первого случая, но во втором случае $x(2x+1)=0$ записал корень $x=2$ вместо $x=-\frac{1}{2}$."),
        1: (r"$0$, $-\dfrac{1}{2}$", r"Ученик решил только второй случай (подмодульное выражение отрицательно) и не рассмотрел первый, где $x=-\frac{2}{3}$."),
        2: (r"$-\dfrac{2}{3}$, $-\dfrac{1}{2}$", r"Ученик разделил обе части уравнения $2x^{2}+x=0$ на $x$ и потерял корень $x=0$.")})
E("G9_TB_ЗПТ_854", "пояснение к варианту $(\\sqrt3;-\\sqrt3)$ противоречило само себе; заменено проверкой подстановкой во второе уравнение: $x+y+xy=-3\\ne0$",
  dnew={1: (r"$(\sqrt{3}; -\sqrt{3})$, $(-\sqrt{3}; \sqrt{3})$", r"Ученик взял пары с $x+y=0$, но во втором уравнении тогда $x+xy+y=0-3=-3\ne0$, то есть эти пары не являются решениями.")})
